draw(X--Y--Z--X);

label("$A$",A,W);
label("$B$",B,NE);
label("$C$",C,SE);
label("$X$",X,E);
label("$Y$",Y,NW);
label("$Z$",Z,SW);

label("$40^\circ$",A+(.2,.06),E);
label("$80^\circ$",C+(0,.15),NW);

label("$50^\circ$",Z+(.2,0),NE);
label("$70^\circ$",Z+(0,.1),NW);
label("$70^\circ$",Y+(0,-.2),SW);
label("$50^\circ$",X+(0,-.3),SW);

[/asy]

Therefore \[\angle YZX=180^\circ-50^\circ - 70^\circ=\boxed{60^\circ}.\]

